namespace ZainRecharge.Domain.Entities;

public enum RechargeStatus
{
    Pending = 1,
    Success = 2,
    Failed = 3,
    Unknown = 4
}

public class RechargeTransaction
{
    public int Id { get; private set; }

    // Generated by SQL Server from Id. The code never sets it.
    public string TransactionId { get; private set; } = null!;

    public string MobileNumber { get; private set; } = null!;
    public decimal Amount { get; private set; }
    public RechargeStatus Status { get; private set; }
    public string? PaymentReference { get; private set; }
    public string? FailureReason { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime UpdatedAt { get; private set; }

    private RechargeTransaction() { } // required by EF Core

    public static RechargeTransaction Create(string mobileNumber, decimal amount, DateTime nowUtc) =>
        new()
        {
            MobileNumber = mobileNumber,
            Amount = amount,
            Status = RechargeStatus.Pending,
            CreatedAt = nowUtc,
            UpdatedAt = nowUtc
        };

    public void MarkSuccess(string paymentReference, DateTime nowUtc)
    {
        EnsureCanBeResolved();
        Status = RechargeStatus.Success;
        PaymentReference = paymentReference;
        FailureReason = null;
        UpdatedAt = nowUtc;
    }

    public void MarkFailed(string reason, DateTime nowUtc)
    {
        EnsureCanBeResolved();
        Status = RechargeStatus.Failed;
        FailureReason = reason;
        UpdatedAt = nowUtc;
    }

    public void MarkUnknown(string reason, DateTime nowUtc)
    {
        if (Status != RechargeStatus.Pending)
            throw new InvalidOperationException($"Transaction {TransactionId} is {Status} and cannot become Unknown.");

        Status = RechargeStatus.Unknown;
        FailureReason = reason;
        UpdatedAt = nowUtc;
    }

    // Pending moves to any final status. Unknown can later be resolved by a status inquiry.
    // Success and Failed are final.
    private void EnsureCanBeResolved()
    {
        if (Status is RechargeStatus.Success or RechargeStatus.Failed)
            throw new InvalidOperationException($"Transaction {TransactionId} is already {Status}.");
    }
}
